-- PARA INSTALACIONES NUEVAS. NO EJECUTAR SOBRE LA BASE EXISTENTE SIN COPIA DE SEGURIDAD.
CREATE DATABASE IF NOT EXISTS isaac_sport_grass CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE isaac_sport_grass;
CREATE TABLE IF NOT EXISTS users(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role ENUM('USER','ADMIN') NOT NULL DEFAULT 'USER',verified BOOLEAN NOT NULL DEFAULT TRUE,verify_token_hash CHAR(64),verify_expires TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS courts(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,sport VARCHAR(50) NOT NULL,district VARCHAR(80) NOT NULL,price DECIMAL(10,2) NOT NULL,available BOOLEAN NOT NULL DEFAULT TRUE,image VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS products(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,category VARCHAR(50) NOT NULL,price DECIMAL(10,2) NOT NULL,stock INT NOT NULL DEFAULT 0,image VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS reservations(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,court_id BIGINT NOT NULL,booking_date DATE NOT NULL,booking_time TIME NOT NULL,status ENUM('CONFIRMADA','CANCELADA','PENDIENTE_PAGO','EN_REVISION','RECHAZADA','EXPIRADA') NOT NULL DEFAULT 'PENDIENTE_PAGO',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,amount_total DECIMAL(10,2) NULL,deposit_amount DECIMAL(10,2) NULL,hold_expires DATETIME NULL,payment_reference VARCHAR(100) NULL,proof_filename VARCHAR(90) NULL,reviewed_at DATETIME NULL,reviewed_by BIGINT NULL,rejection_reason VARCHAR(250) NULL,active_slot VARCHAR(120) GENERATED ALWAYS AS (CASE WHEN status IN ('CONFIRMADA','PENDIENTE_PAGO','EN_REVISION') THEN CONCAT(court_id,'/',booking_date,'/',booking_time) ELSE NULL END) STORED UNIQUE,INDEX ix_reservations_hold(status,hold_expires),FOREIGN KEY (user_id) REFERENCES users(id),FOREIGN KEY (court_id) REFERENCES courts(id));
CREATE TABLE IF NOT EXISTS support_messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,author ENUM('USER','ADMIN') NOT NULL,message VARCHAR(1000) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS orders(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,total DECIMAL(10,2) NOT NULL,status VARCHAR(50) NOT NULL DEFAULT 'PENDIENTE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_items(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY (order_id) REFERENCES orders(id),FOREIGN KEY (product_id) REFERENCES products(id));
INSERT INTO courts(name,sport,district,price,available,image) SELECT * FROM (SELECT 'Arena Fútbol 7' name,'Fútbol' sport,'Santa Anita' district,80 price,1 available,'cancha-futbol.svg' image UNION ALL SELECT 'Club Raqueta Point','Tenis','La Molina',55,1,'cancha-tenis.svg' UNION ALL SELECT 'Hoops Urban Court','Básquet','Ate',65,1,'cancha-basquet.svg' UNION ALL SELECT 'Complejo El Golazo','Fútbol','Surco',110,1,'cancha-futbol.svg' UNION ALL SELECT 'Vóley Arena Sur','Vóley','San Borja',45,1,'cancha-voley.svg' UNION ALL SELECT 'La Bombonera 5','Fútbol','Santa Anita',70,1,'cancha-futbol.svg') x WHERE NOT EXISTS(SELECT 1 FROM courts);
INSERT INTO products(name,category,price,stock,image) SELECT * FROM (SELECT 'Balón Pro Match' name,'Fútbol' category,89 price,15 stock,'producto-balon.svg' image UNION ALL SELECT 'Camiseta ISG Club','Ropa',69,20,'producto-camiseta.svg' UNION ALL SELECT 'Guantes de arquero Pro','Fútbol',95,8,'producto-guantes.svg' UNION ALL SELECT 'Botella Sport Hidratación','Accesorios',29,30,'producto-botella.svg' UNION ALL SELECT 'Cono de entrenamiento','Accesorios',19,12,'producto-cono.svg' UNION ALL SELECT 'Raqueta Court Master','Accesorios',139,6,'producto-raqueta.svg') x WHERE NOT EXISTS(SELECT 1 FROM products);

CREATE TABLE IF NOT EXISTS booking_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY,reservation_id BIGINT NOT NULL,actor_user_id BIGINT NULL,action VARCHAR(40) NOT NULL,notes VARCHAR(300),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reservation_id) REFERENCES reservations(id));
CREATE TABLE IF NOT EXISTS payment_settings (config_key VARCHAR(50) PRIMARY KEY, config_value VARCHAR(500) NOT NULL);
